import os
import re

import pytest

PROJECT = "/project"
PROJECT_FILES = "/project-files"

DEFAULT_PRODUCTION_BRANCHES = {"main", "master", "production", "prod"}

# Stable semver: MAJOR.MINOR.PATCH with no "-prerelease" suffix (build metadata "+x" tolerated).
STABLE_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(\+[0-9A-Za-z.-]+)?$"
)


def _current_branch():
    head_path = os.path.join(PROJECT, ".git", "HEAD")
    if not os.path.isfile(head_path):
        # Worktree/submodule style: .git may be a file pointing elsewhere.
        git_path = os.path.join(PROJECT, ".git")
        if os.path.isfile(git_path):
            with open(git_path, encoding="utf-8") as fh:
                content = fh.read().strip()
            m = re.match(r"gitdir:\s*(.+)", content)
            if m:
                gitdir = m.group(1)
                if not os.path.isabs(gitdir):
                    gitdir = os.path.normpath(os.path.join(PROJECT, gitdir))
                head_path = os.path.join(gitdir, "HEAD")
    if not os.path.isfile(head_path):
        return None
    with open(head_path, encoding="utf-8") as fh:
        head = fh.read().strip()
    m = re.match(r"ref:\s*refs/heads/(.+)", head)
    return m.group(1) if m else None  # None => detached HEAD


def _production_branches():
    """Best-effort: honor a configured production branch, else use common names."""
    candidates = [
        os.path.join(PROJECT, ".lvx.json"),
        os.path.join(PROJECT, ".lvx", "config.json"),
        os.path.join(PROJECT, ".little-versions.json"),
        os.path.join(PROJECT_FILES, "versions.json"),
        os.path.join(PROJECT_FILES, "config.json"),
    ]
    pattern = re.compile(
        r"""["']?(?:production[_-]?branch|prod[_-]?branch)["']?\s*[:=]\s*["']([^"']+)["']""",
        re.IGNORECASE,
    )
    for path in candidates:
        if os.path.isfile(path):
            try:
                with open(path, encoding="utf-8") as fh:
                    m = pattern.search(fh.read())
            except (OSError, UnicodeDecodeError):
                continue
            if m:
                return {m.group(1)}
    return set(DEFAULT_PRODUCTION_BRANCHES)


def test_version_file_is_stable_on_production_branch():
    assert os.path.isdir(PROJECT), "project checkout not mounted at /project"

    branch = _current_branch()
    if branch is None:
        pytest.skip("Detached HEAD or no git metadata; production branch not checked out")

    if branch not in _production_branches():
        pytest.skip(f"Checked-out branch '{branch}' is not the production branch")

    version_path = os.path.join(PROJECT, "VERSION")
    assert os.path.isfile(version_path), "VERSION file is missing on the production branch"

    with open(version_path, encoding="utf-8") as fh:
        version = fh.read().strip()

    assert version, "VERSION file is empty"
    assert STABLE_VERSION_RE.match(version), (
        f"VERSION '{version}' on production branch '{branch}' is not a stable version "
        f"(pre-release suffix or invalid format)"
    )
